<div class="trace-hero card-panel">
    <div><p class="eyebrow">Permission-aware discovery</p><h2>Global Search</h2><p>Search batches, lots, orders, customers, suppliers, products, employees, vehicles, barcodes and RFID tags.</p></div>
    <form method="get" class="trace-search"><input type="hidden" name="route" value="search"><i class="bi bi-search"></i><input class="form-control form-control-lg" type="search" name="q" value="<?= e($query) ?>" minlength="2" placeholder="Type at least 2 characters" autofocus required><button class="btn btn-danger btn-lg">Search</button></form>
</div>
<?php if ($query !== '' && mb_strlen($query) < 2): ?><div class="alert alert-warning">Enter at least two characters.</div><?php endif; ?>
