<?php if ($results): ?><div class="search-results card-panel"><div class="panel-heading"><div><h2><?= e(count($results)) ?> matching records</h2><p>Results are limited by your assigned roles and explicit permissions.</p></div></div><div class="search-result-grid"><?php foreach($results as $result): ?><a href="<?= e($result['url']) ?>"><span class="record-icon"><i class="bi <?= e($result['icon']) ?>"></i></span><span><small><?= e($result['kind']) ?></small><strong><?= e($result['number']) ?></strong><em><?= e(human_status((string) $result['meta'])) ?></em></span><i class="bi bi-chevron-right ms-auto"></i></a><?php endforeach; ?></div></div><?php endif; ?>
